#define WIN32_LEAN_AND_MEAN
#define COBJMACROS
#include <stdint.h>
#include <windows.h>
#include <d3d8.h>
typedef IDirect3DDevice8 FRDevice;
typedef IDirect3DSurface8 FRSurface;
typedef IDirect3DBaseTexture8 FRBase;
#define FR_CLEAR IDirect3DDevice8_Clear
#define FR_LOCK IDirect3DSurface8_LockRect
#define FR_UNLOCK IDirect3DSurface8_UnlockRect
#define FR_SREL IDirect3DSurface8_Release
#define FR_BREL IDirect3DBaseTexture8_Release
#include "d3d8_backend_front_cases.h"
static void fr_setup(FRContext*c){fr_hr(IDirect3DDevice8_SetRenderState(c->d,D3DRS_LIGHTING,0),"FAIL lighting");fr_hr(IDirect3DDevice8_SetRenderState(c->d,D3DRS_ZENABLE,0),"FAIL zenable");fr_hr(IDirect3DDevice8_SetRenderState(c->d,D3DRS_CULLMODE,1),"FAIL cull");fr_hr(IDirect3DDevice8_SetTextureStageState(c->d,0,D3DTSS_COLOROP,2),"FAIL colorop");fr_hr(IDirect3DDevice8_SetTextureStageState(c->d,0,D3DTSS_COLORARG1,2),"FAIL colorarg");fr_hr(IDirect3DDevice8_SetTextureStageState(c->d,0,D3DTSS_ALPHAOP,2),"FAIL alphaop");fr_hr(IDirect3DDevice8_SetTextureStageState(c->d,0,D3DTSS_ALPHAARG1,2),"FAIL alphaarg");fr_hr(IDirect3DDevice8_SetVertexShader(c->d,D3DFVF_XYZRHW|D3DFVF_TEX1|D3DFVF_TEXCOORDSIZE3(0)),"FAIL FVF8");for(UINT state=13;state<=14;state++)fr_hr(IDirect3DDevice8_SetTextureStageState(c->d,0,state,3),"FAIL sampler8");fr_hr(IDirect3DDevice8_SetTextureStageState(c->d,0,25,3),"FAIL addressW8");}
static void fr_draw(FRContext*c,FRBase*parent,UINT kind,BOOL outside,DWORD color){float u=outside?.95f:.5f,v=.5f,w=0;if(kind==2){u=outside?.9f:0;v=0;w=1;}FRVertex vertices[4]={{-.5f,-.5f,.5f,1,u,v,w},{7.5f,-.5f,.5f,1,u,v,w},{-.5f,7.5f,.5f,1,u,v,w},{7.5f,7.5f,.5f,1,u,v,w}};fr_hr(IDirect3DDevice8_SetTexture(c->d,0,parent),"FAIL bind sample");fr_clear(c,0xff010203u);fr_hr(IDirect3DDevice8_BeginScene(c->d),"FAIL BeginScene");fr_hr(IDirect3DDevice8_DrawPrimitiveUP(c->d,D3DPT_TRIANGLESTRIP,2,vertices,sizeof(FRVertex)),"FAIL sample draw");fr_hr(IDirect3DDevice8_EndScene(c->d),"FAIL EndScene");fr_read(c,color);fr_hr(IDirect3DDevice8_SetTexture(c->d,0,NULL),"FAIL unbind sample");}
static HRESULT fr_make(FRContext*c,UINT kind,UINT fmt,UINT w,UINT h,FRSurface**s,FRBase**parent){if(!kind)return IDirect3DDevice8_CreateImageSurface(c->d,w,h,fmt,s);if(kind==1){IDirect3DTexture8*t=NULL;HRESULT hr=IDirect3DDevice8_CreateTexture(c->d,w,h,1,0,fmt,1,&t);if(FAILED(hr))return hr;*parent=(FRBase*)t;return IDirect3DTexture8_GetSurfaceLevel(t,0,s);}IDirect3DCubeTexture8*t=NULL;HRESULT hr=IDirect3DDevice8_CreateCubeTexture(c->d,w,1,0,fmt,1,&t);if(FAILED(hr))return hr;*parent=(FRBase*)t;return IDirect3DCubeTexture8_GetCubeMapSurface(t,4,0,s);}
static HRESULT fr_front(FRContext*c,FRSurface*s){return IDirect3DDevice8_GetFrontBuffer(c->d,s);}
static void fr_read(FRContext*c,DWORD color){FRSurface*cpu=NULL,*back=NULL;FRBase*parent=NULL;fr_hr(fr_make(c,0,21,c->width,c->height,&cpu,&parent),"FAIL read image8");fr_hr(IDirect3DDevice8_GetBackBuffer(c->d,0,0,&back),"FAIL back8");fr_hr(IDirect3DDevice8_CopyRects(c->d,back,NULL,0,cpu,NULL),"FAIL frame read8");D3DLOCKED_RECT l;fr_hr(FR_LOCK(cpu,&l,NULL,16),"FAIL read lock8");for(UINT y=0;y<c->height;y++)for(UINT x=0;x<c->width;x++){fr_check(((DWORD*)((BYTE*)l.pBits+y*l.Pitch))[x]==color,"FAIL frame bytes8");c->words++;}fr_hr(FR_UNLOCK(cpu),"FAIL read unlock8");FR_SREL(back);fr_check(!FR_SREL(cpu),"FAIL read image release8");}
void fr_probe8(HMODULE module,HWND window,UINT mode){IDirect3D8*(WINAPI*make)(UINT)=(void*)(uintptr_t)GetProcAddress(module,"Direct3DCreate8");fr_check(make!=NULL,"FAIL factory8 export");IDirect3D8*r=make(120);fr_check(r!=NULL,"FAIL factory8");D3DPRESENT_PARAMETERS p;ZeroMemory(&p,sizeof(p));p.BackBufferWidth=p.BackBufferHeight=8;p.BackBufferCount=1;p.BackBufferFormat=21;p.SwapEffect=1;p.Windowed=TRUE;p.hDeviceWindow=window;FRContext c={.module=module,.mode=mode,.width=8,.height=8};fr_hr(IDirect3D8_CreateDevice(r,0,1,window,32,&p,&c.d),"FAIL device8");fr_check(IDirect3D8_Release(r)==1,"FAIL root8 release");fr_cases(&c);p.BackBufferWidth=5;p.BackBufferHeight=3;fr_hr(IDirect3DDevice8_Reset(c.d,&p),"FAIL Reset8");fr_post_reset(&c);fr_check(!IDirect3DDevice8_Release(c.d),"FAIL final device8");fr_summary(&c);}
